        for row in adj:
            if len(row) != len(adj):
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and degree
    if is_matrix:
