import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary (0/1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor list and degree array
    if is_matrix:
        neighbors = []
        for i in range(n):
            nbrs = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    nbrs.append(j)
            neighbors.append(nbrs)
    else:
        neighbors = [list(lst) for lst in adj]

    deg = [len(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (deg[v] + 1)
            for u in neighbors[v]:
                c = color[u]
                if c != -1 and c < len(used):
                    used[c] = True
            c = 0
            while c < len(used) and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Welsh-Powell ordering (degree descending)
    def wp_order():
        return sorted(range(n), key=lambda x: deg[x], reverse=True)

    # Helper: Smallest-Last (Matula & Beck) ordering
    def sl_order():
        remaining = set(range(n))
        order = []
        deg_copy = deg[:]
        for _ in range(n):
            v = -1
            min_d = float('inf')
            for u in remaining:
                if deg_copy[u] < min_d:
                    min_d = deg_copy[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    deg_copy[u] -= 1
        return order[::-1]

    # Helper: DSATUR (Brélaz 1979) with optimized saturation updates
    def dsatur():
        color = [-1] * n
        colored = [False] * n
        sat = [0] * n
        neighbor_colors = [set() for _ in range(n)]

        for _ in range(n):
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg) or \
                       (sat[u] == max_sat and deg[u] == max_deg and (v == -1 or u < v)):
                        max_sat = sat[u]
                        max_deg = deg[u]
                        v = u
            used = [False] * n
            for u in neighbors[v]:
                if colored[u]:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            for u in neighbors[v]:
                if not colored[u]:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            v = max(uncolored, key=lambda x: sum(1 for w in neighbors[x] if w in uncolored))
            S = {v}
            uncolored.remove(v)
            W = set()
            for u in neighbors[v]:
                if u in uncolored:
                    W.add(u)
            U = uncolored - W
            while U:
                best_u = -1
                max_w = -1
                min_deg_U = float('inf')
                for u in U:
                    w_count = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if w_count > max_w or \
                       (w_count == max_w and deg_U < min_deg_U) or \
