                        max_w = w_count
                        min_deg_U = deg_U
                        best_u = u
                S.add(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for u in S:
                color[u] = c
            c += 1
        return color

    # Generate initial colorings from multiple heuristics
    colorings = []
    colorings.append(dsatur())          # DSATUR
    colorings.append(greedy_color(wp_order()))  # Welsh-Powell
    colorings.append(greedy_color(sl_order()))  # Smallest-Last
    colorings.append(rlf())             # RLF

    def num_colors(coloring):
