    best_coloring = min(colorings, key=num_colors)
    k = num_colors(best_coloring)

    # Compute lower bound: degeneracy (max core number) using linear-time bucket sort
    def degeneracy():
        if n == 0:
            return 0
        deg_copy = deg[:]
        max_d = max(deg_copy) if n > 0 else 0
        buckets = [[] for _ in range(max_d + 1)]
        for v in range(n):
            d = deg_copy[v]
            if d <= max_d:
                buckets[d].append(v)
        deleted = [False] * n
        curr_deg = deg_copy[:]
        order = []
        for _ in range(n):
            d = 0
            while d <= max_d and not buckets[d]:
                d += 1
            if d > max_d:
                break
            v = buckets[d].pop()
            while deleted[v]:
                if not buckets[d]:
                    d += 1
                    while d <= max_d and not buckets[d]:
                        d += 1
                    if d > max_d:
                        break
                    v = buckets[d].pop()
            deleted[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not deleted[u]:
                    d_u = curr_deg[u]
                    if d_u <= max_d:
                        curr_deg[u] -= 1
                        d_new = curr_deg[u]
                        if d_new <= max_d:
                            buckets[d_new].append(u)
        core = [0] * n
        for v in reversed(order):
            max_nbr_core = 0
            for u in neighbors[v]:
                if core[u] > max_nbr_core:
                    max_nbr_core = core[u]
            core[v] = max_nbr_core + 1
        return max(core) if n > 0 else 0

    lb = degeneracy()
    if k <= lb:
